import React, { useEffect, useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { Link } from 'react-router-dom';
import { fetchMoodEntries, clearMoodErrors } from '../redux/slices/moodSlice';
import MoodEntryCard from '../components/MoodEntryCard';
import './MoodHistory.css';

const MoodHistory = () => {
  const dispatch = useDispatch();
  const { entries, loading, error } = useSelector((state) => state.mood);
  const [currentPage, setCurrentPage] = useState(1);
  const [filter, setFilter] = useState('all');
  
  const ITEMS_PER_PAGE = 10;
  
  useEffect(() => {
    dispatch(fetchMoodEntries());
    
    // Clear any errors when component unmounts
    return () => {
      dispatch(clearMoodErrors());
    };
  }, [dispatch]);
  
  const filteredEntries = () => {
    if (filter === 'all') return entries;
    
    const today = new Date();
    
    if (filter === 'week') {
      const weekAgo = new Date(today);
      weekAgo.setDate(weekAgo.getDate() - 7);
      return entries.filter(entry => new Date(entry.created_at) >= weekAgo);
    }
    
    if (filter === 'month') {
      const monthAgo = new Date(today);
      monthAgo.setMonth(monthAgo.getMonth() - 1);
      return entries.filter(entry => new Date(entry.created_at) >= monthAgo);
    }
    
    if (filter === 'year') {
      const yearAgo = new Date(today);
      yearAgo.setFullYear(yearAgo.getFullYear() - 1);
      return entries.filter(entry => new Date(entry.created_at) >= yearAgo);
    }
    
    return entries;
  };
  
  const totalFilteredEntries = filteredEntries();
  const totalPages = Math.ceil(totalFilteredEntries.length / ITEMS_PER_PAGE);
  
  const getCurrentEntries = () => {
    const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
    const endIndex = startIndex + ITEMS_PER_PAGE;
    return totalFilteredEntries.slice(startIndex, endIndex);
  };
  
  const handlePageChange = (pageNumber) => {
    setCurrentPage(pageNumber);
    window.scrollTo(0, 0);
  };
  
  const handleFilterChange = (newFilter) => {
    setFilter(newFilter);
    setCurrentPage(1); // Reset to first page when filter changes
  };
  
  if (loading && !entries.length) {
    return (
      <div className="container mood-history-page">
        <div className="page-header">
          <h1>Mood History</h1>
          <Link to="/mood-tracker" className="back-button">Back to Tracker</Link>
        </div>
        
        <div className="loading-state">
          <div className="loading-spinner"></div>
          <p>Loading your mood history...</p>
        </div>
      </div>
    );
  }
  
  return (
    <div className="container mood-history-page">
      <div className="page-header">
        <h1>Mood History</h1>
        <Link to="/mood-tracker" className="back-button">Back to Tracker</Link>
      </div>
      
      {error && <div className="error-banner">{error}</div>}
      
      {entries.length === 0 ? (
        <div className="empty-state">
          <div className="empty-icon">📊</div>
          <h2>No mood entries yet</h2>
          <p>Start tracking your mood to build a history of your emotional well-being.</p>
          <Link to="/mood-tracker" className="primary-button">Add Your First Entry</Link>
        </div>
      ) : (
        <>
          <div className="history-filters">
            <button 
              className={`filter-btn ${filter === 'all' ? 'active' : ''}`}
              onClick={() => handleFilterChange('all')}
            >
              All Time
            </button>
            <button 
              className={`filter-btn ${filter === 'year' ? 'active' : ''}`}
              onClick={() => handleFilterChange('year')}
            >
              Past Year
            </button>
            <button 
              className={`filter-btn ${filter === 'month' ? 'active' : ''}`}
              onClick={() => handleFilterChange('month')}
            >
              Past Month
            </button>
            <button 
              className={`filter-btn ${filter === 'week' ? 'active' : ''}`}
              onClick={() => handleFilterChange('week')}
            >
              Past Week
            </button>
          </div>
          
          <div className="entries-count">
            Showing {totalFilteredEntries.length} entries
          </div>
          
          <div className="mood-entries-grid">
            {getCurrentEntries().map((entry) => (
              <MoodEntryCard key={entry.id} entry={entry} />
            ))}
          </div>
          
          {totalPages > 1 && (
            <div className="pagination">
              <button 
                className="page-btn"
                disabled={currentPage === 1}
                onClick={() => handlePageChange(currentPage - 1)}
              >
                Previous
              </button>
              
              {[...Array(totalPages)].map((_, index) => (
                <button
                  key={index}
                  className={`page-btn ${currentPage === index + 1 ? 'active' : ''}`}
                  onClick={() => handlePageChange(index + 1)}
                >
                  {index + 1}
                </button>
              ))}
              
              <button 
                className="page-btn"
                disabled={currentPage === totalPages}
                onClick={() => handlePageChange(currentPage + 1)}
              >
                Next
              </button>
            </div>
          )}
        </>
      )}
    </div>
  );
};

export default MoodHistory;
